using System.Collections.Generic;using System.Linq;using HabitatShift.Core;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public sealed class R10MacroMove {public string habitatId;public Vector2 press;public List<Vector2> path=new List<Vector2>();public RuntimeState result;}
public static class R10MacroMoves { static readonly Vector2[] Steps={Vector2.right,Vector2.left,Vector2.up,Vector2.down}; public static IEnumerable<R10MacroMove> Enumerate(LevelDto level,RulesetDto rules,RuntimeState current){var useful=UsefulAnchors(level,current);foreach(var h in current.habitats.OrderBy(x=>x.id)){var press=h.anchor+Vector2.one*.5f;var destinations=useful.Concat(Steps.Select(d=>h.anchor+d)).Distinct().Where(a=>AxisAllows(h.constraint,h.anchor,a)).OrderBy(a=>Vector2.Distance(h.anchor,a)).ThenBy(a=>a.y).ThenBy(a=>a.x);foreach(var anchor in destinations){if(anchor==h.anchor)continue;var pointer=anchor+Vector2.one*.5f;foreach(var route in Routes(press,pointer)){var s=new ContinuousSession(level,rules,current.Clone());if(!s.BeginDrag(h.id,press))continue;foreach(var point in route)s.MovePointer(point);if(!s.EndDrag(false))continue;var moved=s.Committed.habitats.FirstOrDefault(x=>x.id==h.id);if(moved==null||Vector2.Distance(moved.anchor,anchor)>.001f)continue;yield return new R10MacroMove{habitatId=h.id,press=press,path=route,result=s.Committed.Clone()};break;}}}}
 static IEnumerable<Vector2> UsefulAnchors(LevelDto level,RuntimeState state){var r=new HashSet<Vector2>();foreach(var t in state.sprouts){r.Add(new Vector2(Mathf.Floor(t.position.x),Mathf.Floor(t.position.y)));foreach(var d in Steps)r.Add(new Vector2(Mathf.Floor(t.position.x),Mathf.Floor(t.position.y))+d);}foreach(var e in state.elevators)r.Add(new Vector2(Mathf.Floor(e.entry.x),Mathf.Floor(e.entry.y)));foreach(var c in R10Topology.Analyze(level).chokes)r.Add(new Vector2(c.x,c.y));foreach(var d in R10Topology.Analyze(level).corridors)r.Add(new Vector2(d.x,d.y));return r;}
 static IEnumerable<List<Vector2>> Routes(Vector2 press,Vector2 target){yield return new List<Vector2>{target};if(press.x!=target.x&&press.y!=target.y){yield return new List<Vector2>{new Vector2(target.x,press.y),target};yield return new List<Vector2>{new Vector2(press.x,target.y),target};}}
 static bool AxisAllows(string constraint,Vector2 from,Vector2 to){return constraint!="HORIZONTAL_ONLY"||Mathf.Abs(from.y-to.y)<.001f?constraint!="VERTICAL_ONLY"||Mathf.Abs(from.x-to.x)<.001f:false;}
} }
#endif